create or replace function public.post_gateway_chargeback_financial_journal() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin if new.status in ('chargeback','charged_back','lost') and (tg_op='INSERT' or old.status is distinct from new.status) then perform public.post_gateway_financial_journal(new.user_id,new.transaction_id,new.gateway_id,'chargeback','chargeback:'||new.id::text,new.currency,jsonb_build_array(jsonb_build_object('account_code','merchant_chargebacks','direction','debit','amount',new.amount),jsonb_build_object('account_code','gateway_receivable','direction','credit','amount',new.amount)),jsonb_build_object('source','dispute','dispute_id',new.id,'external_dispute_id',new.external_dispute_id,'reason',new.reason)); end if; return new; end $$;